			mail_link: /^https:\/\//.test(String(v.erste_mail_link || '')) ? v.erste_mail_link : null,
		});
	}
	for (const g of gruppen) g.eintraege.sort((a, b) => (ms(a.seit) || 0) - (ms(b.seit) || 0));
